/**
 * The pinned Python catalogue: interpreter, wheels, import-name map and the
 * standard library names. The data is generated by scripts/pin-python.mjs;
 * this module adds the lookups. Pure, no Node.
 */
import { IMPORTS_DATA, INTERPRETE_DATA, PAQUETS_DATA, STDLIB_DATA } from "./catalogue-data";

export const INTERPRETE: { version: "3.12.10"; url: string; sha256: string; taille: number } = INTERPRETE_DATA;
export const PAQUETS: Record<string, { version: string; url: string; sha256: string; taille: number; dependances: readonly string[] }> = PAQUETS_DATA;
/** Import name to root package. */
export const IMPORTS: Record<string, string> = IMPORTS_DATA;
export const STDLIB: ReadonlySet<string> = new Set(STDLIB_DATA);
/** The libraries a user installs (what a block imports), as Settings lists them:
    every other pinned package is only ever a dependency of one of these. */
export const RACINES: readonly string[] = [...new Set(Object.values(IMPORTS))].sort();

/** The package and its transitive dependencies, dependencies first.
    `paquets` is the installer check's seam (a fake catalogue); a name that
    is not an OWN key (`constructor`, `__proto__`) is unknown. */
export function fermeture(paquet: string, paquets: Record<string, { dependances: readonly string[] }> = PAQUETS): string[] {
	const sortie: string[] = [];
	const vus = new Set<string>();
	const visiter = (nom: string) => {
		if (vus.has(nom)) return;
		vus.add(nom);
		const p = Object.prototype.hasOwnProperty.call(paquets, nom) ? paquets[nom] : undefined;
		if (!p) throw new Error("Unknown package: " + nom);
		for (const d of [...p.dependances].sort()) visiter(d);
		sortie.push(nom);
	};
	visiter(paquet);
	return sortie;
}

export function classerImports(noms: string[]): { stdlib: string[]; connus: string[]; inconnus: string[] } {
	const r = { stdlib: [] as string[], connus: [] as string[], inconnus: [] as string[] };
	for (const n of noms) {
		if (STDLIB.has(n)) r.stdlib.push(n);
		else if (Object.prototype.hasOwnProperty.call(IMPORTS, n)) r.connus.push(n);
		else r.inconnus.push(n);
	}
	return r;
}
